package io.github.turbopro.ism.safety;
import io.github.turbopro.ism.common.api.error.ApiException;import io.github.turbopro.ism.common.infrastructure.authorization.*;import io.github.turbopro.ism.common.infrastructure.tenant.TenantContext;import io.github.turbopro.ism.operation.*;import org.junit.jupiter.api.Test;import java.time.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class SafetyIssueServiceTest{private final SafetyIssueMapper mapper=mock(SafetyIssueMapper.class);private final SafetyIssueService service=new SafetyIssueService(mapper,mock(OperationIdGenerator.class),mock(AuditService.class));
 @Test void deadlineCannotPrecedeDiscovery(){try(var t=TenantContext.open(10,7);var a=auth()){assertThrows(ApiException.class,()->service.create(new SafetyIssueModels.Create("H-1","隐患","20",SafetyIssueModels.Category.BEHAVIOR,SafetyIssueModels.Severity.HIGH,"描述",null,LocalDateTime.now(),LocalDate.now().minusDays(1),"7",0)));}verify(mapper,never()).insert(anyLong(),anyLong(),anyLong(),anyLong(),anyLong(),anyString(),anyString(),anyString(),anyString(),anyString(),any(),any(),any(),anyLong(),anyLong());}
 @Test void closedIssueCannotBeRectified(){when(mapper.get(10,99)).thenReturn(row("CLOSED"));try(var t=TenantContext.open(10,7);var a=auth()){assertThrows(ApiException.class,()->service.rectify(99,new SafetyIssueModels.Rectify("再次整改","100",1)));}verify(mapper,never()).rectify(anyLong(),anyLong(),anyString(),anyLong(),anyLong(),anyInt());}
 private AuthorizationContext.Scope auth(){return AuthorizationContext.open(new PermissionSnapshot(Set.of(),Map.of("safety:issue",DataScope.all()),Set.of()));}private SafetyIssueModels.Row row(String status){var n=LocalDateTime.now();return new SafetyIssueModels.Row(99,1,2,3,"P","项目","S","供应商","H-1","隐患","BEHAVIOR","HIGH","描述",null,n,LocalDate.now(),7,status,null,null,null,null,null,null,null,7,1,n,n);}}
